package android.location;
public class Location { private String provider; private long time; private double latitude,longitude,altitude; private float accuracy,bearing,speed; public Location(String provider){this.provider=provider;} public Location(Location other){provider=other.provider;time=other.time;latitude=other.latitude;longitude=other.longitude;altitude=other.altitude;accuracy=other.accuracy;bearing=other.bearing;speed=other.speed;} public String getProvider(){return provider;} public void setProvider(String p){provider=p;} public long getTime(){return time;} public void setTime(long t){time=t;} public double getLatitude(){return latitude;} public void setLatitude(double v){latitude=v;} public double getLongitude(){return longitude;} public void setLongitude(double v){longitude=v;} public double getAltitude(){return altitude;} public void setAltitude(double v){altitude=v;} public float getAccuracy(){return accuracy;} public void setAccuracy(float v){accuracy=v;} public float getBearing(){return bearing;} public void setBearing(float v){bearing=v;} public float getSpeed(){return speed;} public void setSpeed(float v){speed=v;} }
